//! Request a translation and compare it with the original message.
use crate::primitives::family::Paint;
use crate::primitives::ops_surface::*;
use gpui::{prelude::*, *};
pub struct TranslationRequest {
    pub ticket: u64,
    pub language: String,
}
pub struct MessageTranslation {
    id: SharedString,
    pub author: String,
    pub original: String,
    pub detected: String,
    pub languages: Vec<String>,
    pub credit: String,
    ticket: u64,
    target: String,
    picker: bool,
    cache: std::collections::HashMap<String, (String, String)>,
    translation: String,
    source_visible: bool,
    loading: bool,
    error: bool,
}
impl EventEmitter<TranslationRequest> for MessageTranslation {}
impl MessageTranslation {
    pub fn new(
        id: impl Into<SharedString>,
        author: impl Into<String>,
        original: impl Into<String>,
        languages: Vec<String>,
    ) -> Self {
        Self {
            id: id.into(),
            author: author.into(),
            original: original.into(),
            detected: String::new(),
            languages,
            credit: String::new(),
            ticket: 0,
            target: String::new(),
            picker: false,
            cache: Default::default(),
            translation: String::new(),
            source_visible: true,
            loading: false,
            error: false,
        }
    }
    fn start(&mut self, l: String, cx: &mut Context<Self>) {
        self.ticket += 1;
        self.picker = false;
        if let Some((source, text)) = self.cache.get(&l)
            && source == &self.original
        {
            self.target = l;
            self.translation = text.clone();
            self.source_visible = false;
            self.loading = false;
            self.error = false;
            cx.notify();
            return;
        }
        self.target = l.clone();
        self.source_visible = false;
        self.translation.clear();
        self.loading = true;
        self.error = false;
        cx.emit(TranslationRequest {
            ticket: self.ticket,
            language: l,
        });
        cx.notify()
    }
    pub fn update_translation(
        &mut self,
        ticket: u64,
        text: Result<String, ()>,
        finished: bool,
        cx: &mut Context<Self>,
    ) {
        if ticket != self.ticket || !self.loading {
            return;
        }
        match text {
            Ok(t) => {
                self.translation = t;
                if finished {
                    self.cache.insert(
                        self.target.clone(),
                        (self.original.clone(), self.translation.clone()),
                    );
                }
            }
            Err(()) => self.error = true,
        }
        self.loading = !finished && !self.error;
        cx.notify()
    }
}
impl Render for MessageTranslation {
    fn render(&mut self, w: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let original = self.source_visible || self.translation.is_empty();
        let p = Paint::get(cx);
        let mut shown = if original {
            self.original.clone()
        } else {
            self.translation.clone()
        };
        let end = shown.len();
        let mut styles = stream_highlights(
            "translation-words",
            if original { "" } else { &self.translation },
            w,
            cx,
        );
        if self.loading && !original {
            let n = self
                .translation
                .chars()
                .filter(|c| matches!(c, '.' | '!' | '?' | '。' | '！' | '？'))
                .count()
                .max(1);
            let rest = self
                .original
                .split_inclusive(['.', '!', '?', '。', '！', '？'])
                .skip(n)
                .collect::<String>();
            if !rest.trim().is_empty() {
                shown.push(' ');
                shown.push_str(rest.trim());
                styles.push((
                    end..shown.len(),
                    HighlightStyle {
                        color: Some(p.ink.opacity(0.45)),
                        ..Default::default()
                    },
                ))
            }
        }
        panel(&self.id, 522., cx)
            .child(
                row()
                    .child(avatar(&self.author, 0, cx))
                    .child(title(self.author.clone()))
                    .child(badge(self.detected.clone(), cx)),
            )
            .child(
                div()
                    .min_h(px(85.))
                    .text_size(px(15.))
                    .line_height(px(23.))
                    .text_color(if self.loading && original {
                        p.faint
                    } else {
                        p.ink
                    })
                    .child(StyledText::new(shown).with_highlights(styles)),
            )
            .child(divider(cx))
            .child(
                row().child(
                    btn(
                        "languages",
                        if self.target.is_empty() {
                            tr(cx, "Translate", "翻译").to_string()
                        } else {
                            self.target.clone()
                        },
                        false,
                        cx,
                        |s, _, cx| {
                            s.picker = !s.picker;
                            cx.notify()
                        },
                    )
                    .child(crate::primitives::glyph::icon(
                        if self.picker {
                            crate::primitives::glyph::Glyph::Up
                        } else {
                            crate::primitives::glyph::Glyph::Down
                        },
                        12.,
                        p.secondary,
                    ))
                    .aria_expanded(self.picker),
                ),
            )
            .when(self.picker, |r| {
                r.child(
                    row()
                        .flex_wrap()
                        .children(self.languages.iter().enumerate().map(|(i, l)| {
                            let l = l.clone();
                            btn(
                                ("language", i),
                                l.clone(),
                                self.target == l,
                                cx,
                                move |s, _, cx| s.start(l.clone(), cx),
                            )
                        })),
                )
            })
            .child(
                row()
                    .flex_wrap()
                    .when(!self.translation.is_empty(), |r| {
                        r.child(btn(
                            "original",
                            if self.source_visible {
                                tr(cx, "Show translation", "查看译文")
                            } else {
                                tr(cx, "Show original", "查看原文")
                            },
                            false,
                            cx,
                            |s, _, cx| {
                                s.source_visible = !s.source_visible;
                                cx.notify()
                            },
                        ))
                    })
                    .when(self.error, |r| {
                        r.child(btn(
                            "retry",
                            tr(cx, "Translation failed · Retry", "翻译失败 · 重试"),
                            false,
                            cx,
                            |s, _, cx| s.start(s.target.clone(), cx),
                        ))
                    })
                    .child(note(
                        if self.loading {
                            tr(cx, "Translating…", "翻译中…").to_string()
                        } else {
                            self.credit.clone()
                        },
                        cx,
                    )),
            )
    }
}

//! Focus and activation shared by installed action controls.
use crate::foundation::Theme;
use gpui::{
    App, Context, Div, ElementId, Role, SharedString, Stateful, Window, div, prelude::*, px,
};

pub fn surface(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &App,
) -> Stateful<Div> {
    let label = label.into();
    let c = &Theme::global(cx).tokens.colors;
    let outline = c.focus_outline;
    div()
        .id(id)
        .role(Role::Button)
        .debug_selector(|| label.to_string())
        .aria_label(label)
        .tab_index(0)
        .min_h(px(44.))
        .px_3()
        .flex()
        .items_center()
        .justify_center()
        .rounded(Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(c.border)
        .bg(c.surface)
        .text_color(c.foreground)
        .cursor_pointer()
        .hover(|s| s.opacity(0.8))
        .focus_visible(move |s| {
            s.shadow(vec![gpui::BoxShadow {
                color: outline,
                offset: gpui::point(px(0.), px(0.)),
                blur_radius: px(0.),
                spread_radius: px(2.),
                inset: false,
            }])
        })
}

pub fn activate<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    // GPUI turns a completed Enter/Space press into one keyboard ClickEvent.
    // Registering a second key-down action also toggles on key-up in Web hosts.
    el.on_click(cx.listener(move |v, _, w, cx| f(v, w, cx)))
}

pub fn action<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let label = label.into();
    activate(surface(id, label.clone(), cx).child(label), cx, f)
}

/// Secondary action with a text label and a full keyboard/touch target.
pub fn quiet<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    f: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let c = Theme::global(cx).tokens.colors.clone();
    action(id, label, cx, f)
        .border_0()
        .bg(gpui::transparent_black())
        .text_size(px(12.))
        .text_color(c.text_secondary)
}

/// Monochrome control marks drawn with the same paths on both renderers.
#[derive(Clone, Copy)]
pub enum Mark {
    Hold,
    Check,
    Mic,
    Stop,
    Chevron,
    Up,
    Spark,
    Heart,
}
pub fn mark(kind: Mark, ink: gpui::Hsla) -> impl IntoElement {
    use gpui::{PathBuilder, canvas, point};
    canvas(
        |_, _, _| (),
        move |b, _, w, _| {
            let at = |x: f32, y: f32| point(b.origin.x + px(x), b.origin.y + px(y));
            let mut p = PathBuilder::stroke(px(1.55));
            match kind {
                Mark::Hold => {
                    p.move_to(at(3., 10.));
                    p.curve_to(at(8., 2.5), at(2.4, 2.7));
                    p.curve_to(at(13.3, 8.), at(13.2, 2.5));
                    p.move_to(at(4.6, 13.));
                    p.curve_to(at(5.5, 7.5), at(6., 10.5));
                    p.curve_to(at(10.5, 7.5), at(8., 3.5));
                    p.curve_to(at(9.4, 14.), at(11.1, 10.5));
                    p.move_to(at(8., 7.5));
                    p.curve_to(at(7.2, 12.1), at(8.6, 9.2));
                }
                Mark::Check => {
                    p.move_to(at(2.3, 8.1));
                    p.line_to(at(6.5, 12.));
                    p.line_to(at(13.8, 3.6));
                }
                Mark::Mic => {
                    p.move_to(at(5.4, 4.));
                    p.curve_to(at(10.6, 4.), at(8., -0.9));
                    p.line_to(at(10.6, 7.8));
                    p.curve_to(at(5.4, 7.8), at(8., 12.5));
                    p.line_to(at(5.4, 4.));
                    p.move_to(at(2.5, 7.5));
                    p.curve_to(at(13.5, 7.5), at(8., 16.5));
                    p.move_to(at(8., 12.));
                    p.line_to(at(8., 15.));
                    p.move_to(at(5.5, 15.));
                    p.line_to(at(10.5, 15.));
                }
                Mark::Stop => {
                    p = PathBuilder::fill();
                    p.move_to(at(3.5, 3.5));
                    p.line_to(at(12.5, 3.5));
                    p.line_to(at(12.5, 12.5));
                    p.line_to(at(3.5, 12.5));
                    p.close();
                }
                Mark::Up => {
                    p.move_to(at(8., 13.5));
                    p.line_to(at(8., 2.5));
                    p.move_to(at(3.2, 7.5));
                    p.line_to(at(8., 2.5));
                    p.line_to(at(12.8, 7.5));
                }
                Mark::Spark => {
                    p.move_to(at(8., 1.5));
                    p.curve_to(at(14.5, 8.), at(9.2, 6.7));
                    p.curve_to(at(8., 14.5), at(9.2, 9.3));
                    p.curve_to(at(1.5, 8.), at(6.8, 9.3));
                    p.curve_to(at(8., 1.5), at(6.8, 6.7));
                    p.close();
                }
                Mark::Heart => {
                    p.move_to(at(8., 13.8));
                    p.cubic_bezier_to(at(1.8, 5.6), at(5., 11.5), at(1.8, 8.6));
                    p.cubic_bezier_to(at(8., 4.4), at(1.8, 2.), at(5.8, 1.6));
                    p.cubic_bezier_to(at(14.2, 5.6), at(10.2, 1.6), at(14.2, 2.));
                    p.cubic_bezier_to(at(8., 13.8), at(14.2, 8.6), at(11., 11.5));
                    p.close();
                }
                Mark::Chevron => {
                    p.move_to(at(5., 6.5));
                    p.line_to(at(8., 9.5));
                    p.line_to(at(11., 6.5));
                }
            }
            if let Ok(path) = p.build() {
                w.paint_path(path, ink);
            }
        },
    )
    .size(px(16.))
    .flex_none()
}

/// Optional host language for labels owned by action controls; English is the default.
#[derive(Clone, Copy, Default, PartialEq, Eq)]
pub enum UiLanguage {
    #[default]
    English,
    Chinese,
}
impl gpui::Global for UiLanguage {}
impl UiLanguage {
    pub fn current(cx: &App) -> Self {
        cx.try_global::<Self>().copied().unwrap_or_default()
    }
    pub fn text<'a>(self, english: &'a str, chinese: &'a str) -> &'a str {
        match self {
            Self::English => english,
            Self::Chinese => chinese,
        }
    }
}

//! Editable Unicode text, IME composition and selection shared by KUI fields.
use crate::primitives::family::Paint;
use gpui::{prelude::*, *};
use std::{ops::Range, time::Duration};
use unicode_segmentation::UnicodeSegmentation;

#[derive(Clone, Copy, PartialEq, Eq)]
pub enum InputMode {
    Single,
    Multi,
    Password,
    Search,
    Combobox,
    InlineMulti,
}
impl InputMode {
    fn multiline(self) -> bool {
        matches!(self, Self::Multi | Self::InlineMulti)
    }
}
#[derive(Clone, Debug, PartialEq, Eq)]
pub enum EditEvent {
    Changed,
    Submitted,
    Escape,
    Navigate(bool),
    Focused,
    Blurred,
}
struct Layout {
    bounds: Bounds<Pixels>,
    origin: Point<Pixels>,
    rows: Vec<WrappedLine>,
    line: Pixels,
    // Only populated when the painted text differs from the editable text.
    mask: Vec<usize>,
}
impl Layout {
    fn visible_index(&self, index: usize) -> usize {
        if self.mask.is_empty() {
            index
        } else {
            self.mask.partition_point(|p| *p < index) * '•'.len_utf8()
        }
    }
    fn index(&self, index: usize) -> usize {
        if self.mask.is_empty() {
            index
        } else {
            *self.mask.get(index / '•'.len_utf8()).unwrap_or_else(|| {
                self.mask
                    .last()
                    .expect("masked layout has a terminal offset")
            })
        }
    }
    fn at(&self, byte: usize) -> Point<Pixels> {
        let mut remain = self.visible_index(byte);
        let mut p = self.origin;
        for row in &self.rows {
            if remain <= row.len() {
                return p + row
                    .position_for_index(remain, self.line)
                    .unwrap_or_default();
            }
            remain -= row.len() + 1;
            p.y += row.size(self.line).height;
        }
        p
    }
    fn hit(&self, p: Point<Pixels>) -> usize {
        let mut local = p - self.origin;
        local.y = local.y.max(px(0.));
        let mut offset = 0;
        for row in &self.rows {
            let height = row.size(self.line).height;
            if local.y < height {
                return self.index(
                    offset
                        + row
                            .closest_index_for_position(local, self.line)
                            .unwrap_or_else(|v| v),
                );
            }
            local.y -= height;
            offset += row.len() + 1;
        }
        self.index(offset.saturating_sub(1))
    }
    fn rects(&self, range: Range<usize>) -> Vec<Bounds<Pixels>> {
        let a = self.at(range.start);
        let b = self.at(range.end);
        let mut y = a.y;
        let mut rects = Vec::new();
        while y <= b.y {
            let x = if y == a.y { a.x } else { self.bounds.left() };
            let end = if y == b.y { b.x } else { self.bounds.right() };
            rects.push(Bounds::new(
                point(x, y),
                size((end - x).max(px(1.)), self.line),
            ));
            y += self.line
        }
        rects
    }
}
#[derive(Clone)]
struct Snapshot {
    text: String,
    anchor: usize,
    caret: usize,
}
/// An embedding host may hand the wheel back to the document at the scroll limits.
pub struct EditorScrollRegion(pub fn(Bounds<Pixels>, bool, bool));
impl Global for EditorScrollRegion {}

// On the web the browser may send an ordinary, unflagged printable keydown
// before compositionstart. Let its textarea deliver text via input/composition
// instead of letting the GPUI keydown fallback insert the opening letter too.
#[cfg(target_family = "wasm")]
fn browser_text_input() -> Subscription {
    use wasm_bindgen::prelude::*;
    #[wasm_bindgen(inline_js = r#"
        export function listenForEditorText() {
            const controller = new AbortController();
            const options = { capture: true, signal: controller.signal };
            function attach(input) {
                let composing = false;
                input.addEventListener('compositionstart', () => { composing = true; }, options);
                input.addEventListener('compositionend', () => { composing = false; }, options);
                input.addEventListener('blur', () => { composing = false; }, options);
                input.addEventListener('keydown', event => {
                    if (input.readOnly) return;
                    const shortcut = event.metaKey || (event.ctrlKey && !event.getModifierState('AltGraph'));
                    const textKey = [...event.key].length === 1 || event.key === 'Dead';
                    if (composing || event.isComposing || event.keyCode === 229 || (!shortcut && textKey)) {
                        // Preserve the default action that drives the IME and regular typing.
                        event.stopImmediatePropagation();
                    }
                }, options);
            }
            if (document.activeElement instanceof HTMLTextAreaElement) {
                attach(document.activeElement);
            } else {
                // GPUI may assign editor focus just before it focuses the DOM mirror.
                const onFocus = event => {
                    if (!(event.target instanceof HTMLTextAreaElement)) return;
                    document.removeEventListener('focusin', onFocus, true);
                    attach(event.target);
                };
                document.addEventListener('focusin', onFocus, options);
            }
            return controller;
        }
        export function stopListeningForEditorText(controller) { controller.abort(); }
    "#)]
    extern "C" {
        #[wasm_bindgen(js_name = listenForEditorText)]
        fn listen() -> JsValue;
        #[wasm_bindgen(js_name = stopListeningForEditorText)]
        fn stop(controller: JsValue);
    }
    let controller = listen();
    Subscription::new(move || stop(controller))
}

/// Optional glyph runs for an attributed document. Text, IME and selection retain the normal input path.
pub type RunStyler = std::rc::Rc<dyn Fn(&str, &TextRun) -> Vec<TextRun>>;
pub struct Editor {
    run_styler: Option<RunStyler>,
    label: SharedString,
    placeholder: SharedString,
    pub(crate) expanded: Option<bool>,
    // A closed picker paints the committed option while keeping its query buffer empty.
    pub(crate) committed_label: Option<SharedString>,
    pub mode: InputMode,
    value: String,
    anchor: usize,
    caret: usize,
    marked: Option<Range<usize>>,
    pub focus: FocusHandle,
    pub revealed: bool,
    pub disabled: bool,
    pub font_size: f32,
    pub description: SharedString,
    layout: Option<Layout>,
    scroll: Point<Pixels>,
    follow_caret: bool,
    dragging: bool,
    history: Vec<Snapshot>,
    redo: Vec<Snapshot>,
    cursor: bool,
    blink: Option<Task<()>>,
    #[cfg(target_family = "wasm")]
    browser_keys: Option<Subscription>,
    _listeners: Vec<Subscription>,
}
impl EventEmitter<EditEvent> for Editor {}
impl Focusable for Editor {
    fn focus_handle(&self, _: &App) -> FocusHandle {
        self.focus.clone()
    }
}
fn from_utf16(s: &str, offset: usize) -> usize {
    let mut units = 0;
    for (i, ch) in s.char_indices() {
        if units + ch.len_utf16() > offset {
            return i;
        }
        units += ch.len_utf16()
    }
    s.len()
}
impl Editor {
    pub fn new(
        label: impl Into<SharedString>,
        mode: InputMode,
        w: &mut Window,
        cx: &mut Context<Self>,
    ) -> Self {
        let focus = cx.focus_handle().tab_stop(true);
        let entered = cx.on_focus(&focus, w, |s: &mut Self, _, cx| {
            #[cfg(target_family = "wasm")]
            {
                s.browser_keys = Some(browser_text_input());
            }
            s.cursor = true;
            s.blink = Some(cx.spawn(async move |this, cx| {
                loop {
                    cx.background_executor()
                        .timer(Duration::from_millis(530))
                        .await;
                    if this
                        .update(cx, |s, cx| {
                            s.cursor = !s.cursor;
                            cx.notify()
                        })
                        .is_err()
                    {
                        break;
                    }
                }
            }));
            cx.emit(EditEvent::Focused);
            cx.notify()
        });
        let left = cx.on_blur(&focus, w, |s: &mut Self, _, cx| {
            #[cfg(target_family = "wasm")]
            {
                s.browser_keys = None;
            }
            s.blink = None;
            s.dragging = false;
            s.marked = None;
            cx.emit(EditEvent::Blurred);
            cx.notify()
        });
        Self {
            label: label.into(),
            run_styler: None,
            placeholder: "".into(),
            expanded: None,
            committed_label: None,
            mode,
            value: String::new(),
            anchor: 0,
            caret: 0,
            marked: None,
            focus,
            revealed: false,
            disabled: false,
            font_size: 14.,
            description: "".into(),
            layout: None,
            scroll: Default::default(),
            follow_caret: true,
            dragging: false,
            history: vec![],
            redo: vec![],
            cursor: true,
            blink: None,
            #[cfg(target_family = "wasm")]
            browser_keys: None,
            _listeners: vec![entered, left],
        }
    }
    pub fn set_run_styler(&mut self, styler: RunStyler) {
        self.run_styler = Some(styler)
    }
    /// The normalized byte range, including a collapsed caret.
    pub fn selection(&self) -> Range<usize> {
        self.selected()
    }
    pub fn value(&self) -> &str {
        &self.value
    }
    pub fn set_placeholder(&mut self, s: impl Into<SharedString>) {
        self.placeholder = s.into()
    }
    pub fn set_value(&mut self, s: impl Into<String>, w: &Window, cx: &mut Context<Self>) {
        let value = self.normalize(&s.into());
        if self.value == value {
            return;
        }
        self.value = value;
        self.caret = self.value.len();
        self.anchor = self.caret;
        self.marked = None;
        self.history.clear();
        self.redo.clear();
        self.changed(w, cx)
    }
    pub fn focus(&self, w: &mut Window, cx: &mut App) {
        if !self.disabled {
            self.focus.focus(w, cx)
        }
    }
    pub fn select_all(&mut self, w: &Window, cx: &mut Context<Self>) {
        self.anchor = 0;
        self.select(self.value.len(), true, w, cx)
    }
    fn normalize(&self, s: &str) -> String {
        let s = s.replace("\r\n", "\n").replace('\r', "\n");
        if self.mode.multiline() {
            s
        } else {
            s.replace('\n', " ")
        }
    }
    fn selected(&self) -> Range<usize> {
        self.anchor.min(self.caret)..self.anchor.max(self.caret)
    }
    fn bytes(&self, r: Range<usize>) -> Range<usize> {
        let a = from_utf16(&self.value, r.start);
        a..from_utf16(&self.value, r.end).max(a)
    }
    fn units(&self, r: Range<usize>) -> Range<usize> {
        self.value[..r.start].encode_utf16().count()..self.value[..r.end].encode_utf16().count()
    }
    fn select(&mut self, offset: usize, extend: bool, w: &Window, cx: &mut Context<Self>) {
        self.caret = offset.min(self.value.len());
        if !extend {
            self.anchor = self.caret
        }
        self.follow_caret = true;
        self.cursor = true;
        w.notify_text_selection_changed(&self.focus);
        cx.notify()
    }
    fn changed(&mut self, w: &Window, cx: &mut Context<Self>) {
        self.cursor = true;
        self.follow_caret = true;
        self.layout = None;
        w.notify_text_input_changed(&self.focus);
        cx.emit(EditEvent::Changed);
        cx.notify()
    }
    fn snapshot(&self) -> Snapshot {
        Snapshot {
            text: self.value.clone(),
            anchor: self.anchor,
            caret: self.caret,
        }
    }
    fn edit(
        &mut self,
        range: Option<Range<usize>>,
        text: &str,
        composition: bool,
        sel: Option<Range<usize>>,
        w: &Window,
        cx: &mut Context<Self>,
    ) {
        if self.disabled {
            return;
        }
        let range = range
            .map(|r| self.bytes(r))
            .or_else(|| self.marked.clone())
            .unwrap_or_else(|| self.selected());
        let text = self.normalize(text);
        if self.marked.is_none() {
            self.history.push(self.snapshot());
            if self.history.len() > 100 {
                self.history.remove(0);
            }
            self.redo.clear()
        }
        self.value.replace_range(range.clone(), &text);
        let end = range.start + text.len();
        self.caret = end;
        self.anchor = end;
        self.marked = (composition && !text.is_empty()).then_some(range.start..end);
        if composition && let Some(sel) = sel {
            self.anchor = range.start + from_utf16(&text, sel.start);
            self.caret = range.start + from_utf16(&text, sel.end)
        }
        self.changed(w, cx)
    }
    fn undo(&mut self, forward: bool, w: &Window, cx: &mut Context<Self>) {
        let old = if forward {
            self.redo.pop()
        } else {
            self.history.pop()
        };
        if let Some(old) = old {
            let current = self.snapshot();
            if forward {
                self.history.push(current)
            } else {
                self.redo.push(current)
            }
            self.value = old.text;
            self.anchor = old.anchor;
            self.caret = old.caret;
            self.marked = None;
            self.changed(w, cx)
        }
    }
    fn boundary(&self, right: bool, word: bool) -> usize {
        if right {
            let tail = &self.value[self.caret..];
            self.caret
                + if word {
                    tail.split_word_bound_indices()
                        .next()
                        .map_or(0, |(_, s)| s.len())
                } else {
                    tail.graphemes(true).next().map_or(0, str::len)
                }
        } else {
            let head = &self.value[..self.caret];
            if word {
                head.split_word_bound_indices()
                    .next_back()
                    .map_or(0, |(i, _)| i)
            } else {
                head.grapheme_indices(true)
                    .next_back()
                    .map_or(0, |(i, _)| i)
            }
        }
    }
    fn key(&mut self, e: &KeyDownEvent, w: &mut Window, cx: &mut Context<Self>) {
        if self.disabled || self.marked.is_some() {
            return;
        }
        let m = e.keystroke.modifiers;
        let k = e.keystroke.key.as_str();
        let cmd = m.platform || m.control;
        let r = self.selected();
        match k {
            "a" if cmd => self.select_all(w, cx),
            "z" if cmd => self.undo(m.shift, w, cx),
            "y" if cmd => self.undo(true, w, cx),
            "c" | "x" if cmd => {
                if !r.is_empty() && self.mode != InputMode::Password {
                    cx.write_to_clipboard(ClipboardItem::new_string(self.value[r].to_owned()));
                    if k == "x" {
                        self.edit(None, "", false, None, w, cx)
                    }
                }
            }
            "v" if cmd && !cfg!(target_family = "wasm") => {
                if let Some(text) = cx.read_from_clipboard().and_then(|v| v.text()) {
                    self.edit(None, &text, false, None, w, cx)
                }
            }
            "left" | "right" => {
                let right = k == "right";
                let to = if !m.shift && !r.is_empty() {
                    if right { r.end } else { r.start }
                } else if m.platform {
                    self.line_edge(right)
                } else {
                    self.boundary(right, m.alt || m.control)
                };
                self.select(to, m.shift, w, cx)
            }
            "home" | "end" => {
                let end = k == "end";
                let to = if cmd {
                    if end { self.value.len() } else { 0 }
                } else {
                    self.line_edge(end)
                };
                self.select(to, m.shift, w, cx)
            }
            "backspace" | "delete" => {
                if r.is_empty() {
                    self.anchor = self.boundary(k == "delete", m.alt || m.control)
                }
                if !self.selected().is_empty() {
                    self.edit(None, "", false, None, w, cx)
                }
            }
            "up" | "down" if self.mode == InputMode::Combobox => {
                cx.emit(EditEvent::Navigate(k == "down"))
            }
            "up" | "down" if self.mode.multiline() => {
                if let Some(l) = &self.layout {
                    let mut p = l.at(self.caret);
                    p.y += if k == "down" {
                        l.line * 1.5
                    } else {
                        -l.line * 0.5
                    };
                    self.select(l.hit(p), m.shift, w, cx)
                }
            }
            "enter"
                if self.mode == InputMode::Multi
                    || (self.mode == InputMode::InlineMulti && m.shift) =>
            {
                self.edit(None, "\n", false, None, w, cx)
            }
            "enter" => cx.emit(EditEvent::Submitted),
            "escape" => cx.emit(EditEvent::Escape),
            _ => return,
        }
        w.prevent_default();
        cx.stop_propagation()
    }
    fn line_edge(&self, end: bool) -> usize {
        if end {
            self.value[self.caret..]
                .find('\n')
                .map_or(self.value.len(), |n| self.caret + n)
        } else {
            self.value[..self.caret].rfind('\n').map_or(0, |i| i + 1)
        }
    }
}
impl EntityInputHandler for Editor {
    fn text_for_range(
        &mut self,
        r: Range<usize>,
        actual: &mut Option<Range<usize>>,
        _: &mut Window,
        _: &mut Context<Self>,
    ) -> Option<String> {
        let r = self.bytes(r);
        *actual = Some(self.units(r.clone()));
        Some(self.value[r].to_owned())
    }
    fn selected_text_range(
        &mut self,
        _: bool,
        _: &mut Window,
        _: &mut Context<Self>,
    ) -> Option<UTF16Selection> {
        Some(UTF16Selection {
            range: self.units(self.selected()),
            reversed: self.anchor > self.caret,
        })
    }
    fn text_length_utf16(&mut self, _: &mut Window, _: &mut Context<Self>) -> Option<usize> {
        Some(self.value.encode_utf16().count())
    }
    fn set_selected_text_range(&mut self, r: Range<usize>, w: &mut Window, cx: &mut Context<Self>) {
        let r = self.bytes(r);
        self.anchor = r.start;
        self.select(r.end, true, w, cx)
    }
    fn marked_text_range(&self, _: &mut Window, _: &mut Context<Self>) -> Option<Range<usize>> {
        self.marked.clone().map(|r| self.units(r))
    }
    fn unmark_text(&mut self, w: &mut Window, cx: &mut Context<Self>) {
        self.marked = None;
        w.notify_text_input_changed(&self.focus);
        cx.notify()
    }
    fn replace_text_in_range(
        &mut self,
        r: Option<Range<usize>>,
        s: &str,
        w: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.edit(r, s, false, None, w, cx)
    }
    fn replace_and_mark_text_in_range(
        &mut self,
        r: Option<Range<usize>>,
        s: &str,
        sel: Option<Range<usize>>,
        w: &mut Window,
        cx: &mut Context<Self>,
    ) {
        self.edit(r, s, true, sel, w, cx)
    }
    fn bounds_for_range(
        &mut self,
        r: Range<usize>,
        _: Bounds<Pixels>,
        _: &mut Window,
        _: &mut Context<Self>,
    ) -> Option<Bounds<Pixels>> {
        self.layout
            .as_ref()?
            .rects(self.bytes(r))
            .into_iter()
            .next()
    }
    fn selection_bounds_for_range(
        &mut self,
        r: Range<usize>,
        _: Bounds<Pixels>,
        _: &mut Window,
        _: &mut Context<Self>,
    ) -> Vec<Bounds<Pixels>> {
        self.layout
            .as_ref()
            .map_or_else(Vec::new, |l| l.rects(self.bytes(r)))
    }
    fn character_index_for_point(
        &mut self,
        p: Point<Pixels>,
        _: &mut Window,
        _: &mut Context<Self>,
    ) -> Option<usize> {
        let n = self.layout.as_ref()?.hit(p).min(self.value.len());
        Some(self.units(n..n).start)
    }
    fn accepts_text_input(&self, _: &mut Window, _: &mut Context<Self>) -> bool {
        !self.disabled
    }
    fn text_input_configuration(
        &mut self,
        _: &mut Window,
        _: &mut Context<Self>,
    ) -> TextInputConfiguration {
        TextInputConfiguration {
            autocorrect: false,
            suggestions: self.mode != InputMode::Password,
            input_action: match self.mode {
                InputMode::Multi => TextInputAction::Enter,
                InputMode::Combobox | InputMode::Search => TextInputAction::Search,
                _ => TextInputAction::Done,
            },
            ..Default::default()
        }
    }
}
impl Editor {
    fn paint(&mut self, b: Bounds<Pixels>, w: &mut Window, cx: &mut Context<Self>) {
        let focused = self.focus.is_focused(w);
        let p = Paint::get(cx);
        let blank = self.value.is_empty();
        let masked = self.mode == InputMode::Password && !self.revealed && !blank;
        let mask = if masked {
            self.value
                .grapheme_indices(true)
                .map(|(i, _)| i)
                .chain(std::iter::once(self.value.len()))
                .collect::<Vec<_>>()
        } else {
            vec![]
        };
        let text: SharedString = if blank {
            self.committed_label
                .clone()
                .unwrap_or_else(|| self.placeholder.clone())
        } else if masked {
            "•".repeat(mask.len() - 1).into()
        } else {
            self.value.clone().into()
        };
        let mut run = w.text_style().to_run(text.len());
        run.color = if (blank && self.committed_label.is_none()) || self.disabled {
            p.secondary
        } else {
            p.ink
        };
        let line = px(self.font_size + 7.);
        let multi = self.mode.multiline();
        let styled = if !blank && !masked {
            self.run_styler.as_ref().map(|f| f(&text, &run))
        } else {
            None
        };
        let rows = w
            .text_system()
            .shape_text(
                text,
                px(self.font_size),
                styled.as_deref().unwrap_or(std::slice::from_ref(&run)),
                multi.then_some(b.size.width.max(px(1.))),
                None,
            )
            .unwrap_or_default()
            .into_vec();
        let height = rows
            .iter()
            .fold(px(0.), |sum, row| sum + row.size(line).height);
        let top = if multi {
            b.top()
        } else {
            b.top() + (b.size.height - line) * 0.5
        };
        let origin = point(b.left(), top);
        let mut layout = Layout {
            bounds: b,
            origin,
            rows,
            mask,
            line,
        };
        let pt = layout.at(self.caret) - origin;
        if self.follow_caret {
            let keep = |scroll: Pixels, pos: Pixels, room: Pixels| {
                scroll.min(pos).max(pos - room).max(px(0.))
            };
            self.scroll.x = if multi {
                px(0.)
            } else {
                keep(self.scroll.x, pt.x, b.size.width - px(2.))
            };
            self.scroll.y = keep(self.scroll.y, pt.y, (b.size.height - line).max(px(0.)));
            self.follow_caret = false
        }
        // A newly mounted flex child can first paint at width zero; never retain
        // that transient horizontal offset once the real width is known.
        let longest = layout
            .rows
            .iter()
            .map(|row| row.size(line).width)
            .max()
            .unwrap_or(px(0.));
        self.scroll.x = self
            .scroll
            .x
            .min((longest + px(2.) - b.size.width).max(px(0.)));
        self.scroll.y = self.scroll.y.min((height - b.size.height).max(px(0.)));
        if self.mode == InputMode::Multi
            && let Some(host) = cx.try_global::<EditorScrollRegion>()
        {
            (host.0)(
                b,
                self.scroll.y > px(0.),
                self.scroll.y + b.size.height < height,
            );
        }
        layout.origin -= self.scroll;
        w.with_content_mask(Some(ContentMask { bounds: b }), |w| {
            if focused && !self.selected().is_empty() {
                for rect in layout.rects(self.selected()) {
                    w.paint_quad(fill(rect, p.ink.opacity(0.19)))
                }
            }
            let mut pos = layout.origin;
            for row in &layout.rows {
                let _ = row.paint(pos, line, TextAlign::Left, None, w, cx);
                pos.y += row.size(line).height;
            }
            if let Some(mark) = &self.marked {
                for rect in layout.rects(mark.clone()) {
                    w.paint_quad(fill(
                        Bounds::new(
                            point(rect.left(), rect.bottom() - px(1.)),
                            size(rect.size.width, px(1.)),
                        ),
                        p.ink,
                    ))
                }
            }
            if focused
                && self.cursor
                && self.selected().is_empty()
                && self.committed_label.is_none()
            {
                let caret = layout.at(self.caret);
                w.paint_quad(fill(
                    Bounds::new(caret + point(px(0.), px(2.)), size(px(1.), line - px(4.))),
                    p.ink,
                ))
            }
        });
        self.layout = Some(layout);
        if !self.disabled {
            w.handle_input(&self.focus, ElementInputHandler::new(b, cx.entity()), cx)
        }
    }
}
impl Render for Editor {
    fn render(&mut self, _: &mut Window, cx: &mut Context<Self>) -> impl IntoElement {
        let entity = cx.entity();
        let name = self.label.clone();
        let role = match self.mode {
            InputMode::Password => Role::PasswordInput,
            InputMode::Multi | InputMode::InlineMulti => Role::MultilineTextInput,
            InputMode::Search => Role::SearchInput,
            InputMode::Combobox => Role::ComboBox,
            _ => Role::TextInput,
        };
        div()
            .id("editor")
            .debug_selector(move || name.to_string())
            .track_focus(&self.focus)
            .tab_stop(!self.disabled)
            .role(role)
            .aria_label(self.label.clone())
            .aria_description(self.description.clone())
            .aria_placeholder(self.placeholder.clone())
            .when_some(self.expanded, |e, open| e.aria_expanded(open))
            .when(self.mode != InputMode::Password, |e| {
                e.aria_value(
                    self.committed_label
                        .clone()
                        .unwrap_or_else(|| self.value.clone().into()),
                )
            })
            .size_full()
            .min_w_0()
            .overflow_hidden()
            .cursor(CursorStyle::IBeam)
            .on_key_down(cx.listener(Self::key))
            .on_mouse_down(
                MouseButton::Left,
                cx.listener(|s, e: &MouseDownEvent, w, cx| {
                    if s.disabled {
                        return;
                    }
                    s.focus(w, cx);
                    w.request_virtual_keyboard();
                    let pos = s
                        .layout
                        .as_ref()
                        .map_or(0, |l| l.hit(e.position))
                        .min(s.value.len());
                    if e.click_count >= 3 {
                        s.select_all(w, cx)
                    } else if e.click_count == 2 {
                        let r = s
                            .value
                            .split_word_bound_indices()
                            .find(|(i, t)| pos < *i + t.len())
                            .map(|(i, t)| i..i + t.len())
                            .unwrap_or(pos..pos);
                        s.anchor = r.start;
                        s.select(r.end, true, w, cx)
                    } else {
                        s.select(pos, e.modifiers.shift, w, cx)
                    }
                    s.dragging = true;
                }),
            )
            .on_mouse_move(cx.listener(|s, e: &MouseMoveEvent, w, cx| {
                if s.dragging
                    && e.pressed_button == Some(MouseButton::Left)
                    && let Some(l) = &s.layout
                {
                    s.select(l.hit(e.position), true, w, cx)
                }
            }))
            .on_mouse_up(
                MouseButton::Left,
                cx.listener(|s, _, _, _| s.dragging = false),
            )
            .on_mouse_up_out(
                MouseButton::Left,
                cx.listener(|s, _, _, _| s.dragging = false),
            )
            .on_scroll(cx.listener(|s, e: &ScrollEvent, _, cx| {
                if s.mode.multiline()
                    && let Some(l) = &s.layout
                {
                    let max = l
                        .rows
                        .iter()
                        .map(|r| f32::from(r.size(l.line).height))
                        .sum::<f32>()
                        - f32::from(l.bounds.size.height);
                    let next =
                        (s.scroll.y - e.delta.pixel_delta(l.line).y).clamp(px(0.), px(max.max(0.)));
                    if next != s.scroll.y {
                        s.scroll.y = next;
                        s.follow_caret = false;
                        cx.stop_propagation();
                        cx.notify()
                    }
                }
            }))
            .child(
                canvas(
                    |_, _, _| (),
                    move |bounds, _, w, cx| entity.update(cx, |s, cx| s.paint(bounds, w, cx)),
                )
                .size_full(),
            )
    }
}

//! Compact action surfaces scoped to the button family.
use crate::foundation::{AccentPalette, Theme, ThemeMode};
use gpui::{prelude::*, *};
use web_time::Instant;
#[derive(Debug, Clone, Copy, Default, PartialEq, Eq)]
pub enum Tone {
    #[default]
    Surface,
    Primary,
    Muted,
    Danger,
    Success,
    Clear,
}
#[derive(Clone, Copy)]
pub struct Paint {
    pub stage: Hsla,
    pub panel: Hsla,
    pub tray: Hsla,
    pub hover: Hsla,
    pub ink: Hsla,
    pub secondary: Hsla,
    pub faint: Hsla,
    pub line: Hsla,
    pub bright: Hsla,
    pub(crate) focus: Hsla,
    pub inverse: Hsla,
    pub(crate) neutral_inverse: Hsla,
    accent: AccentPalette,
    pub danger: Hsla,
    pub success: Hsla,
}
impl Paint {
    pub fn get(cx: &App) -> Self {
        Self::for_theme(Theme::global(cx))
    }
    pub(crate) fn for_theme(theme: &Theme) -> Self {
        let mut paint = Self::for_mode(theme.mode);
        let tint = theme.accent.for_mode(theme.mode);
        if tint.is_transparent() {
            return paint;
        }
        paint.accent = theme.accent;
        paint.bright = paint.bright.blend(tint);
        paint.focus = theme.tokens.colors.focus_outline;
        paint.inverse = paint.accent.on_fill(paint.bright, paint.neutral_inverse);
        paint.hover = paint.hover.blend(tint.opacity(0.12));
        paint
    }
    pub(crate) fn primary_hover(self, strength: f32) -> Hsla {
        self.bright.blend(
            self.accent
                .hover_tint(self.bright, self.inverse, strength)
                .opacity(strength),
        )
    }
    pub fn for_mode(mode: ThemeMode) -> Self {
        let dark = mode == ThemeMode::Dark;
        let [
            stage,
            panel,
            tray,
            hover,
            ink,
            secondary,
            faint,
            line,
            bright,
            inverse,
            danger,
        ] = if dark {
            [
                0x242424, 0x191919, 0x303030, 0x353535, 0xf2f2f2, 0xb5b5b5, 0x898989, 0x2b2b2b,
                0xf2f2f2, 0x141414, 0xff746f,
            ]
        } else {
            [
                0xf5f5f5, 0xffffff, 0xffffff, 0xe9e9e9, 0x1a1a1a, 0x575757, 0x747474, 0xe2e2e2,
                0x181818, 0xfafafa, 0xbd302c,
            ]
        };
        Self {
            stage: rgb(stage).into(),
            panel: rgb(panel).into(),
            tray: rgb(tray).into(),
            hover: rgb(hover).into(),
            ink: rgb(ink).into(),
            secondary: rgb(secondary).into(),
            faint: rgb(faint).into(),
            line: rgb(line).into(),
            bright: rgb(bright).into(),
            focus: rgb(bright).into(),
            inverse: rgb(inverse).into(),
            neutral_inverse: rgb(inverse).into(),
            accent: AccentPalette::default(),
            danger: rgb(danger).into(),
            success: rgb(if dark { 0x53d986 } else { 0x008039 }).into(),
        }
    }
    pub fn colors(self, t: Tone) -> (Hsla, Hsla) {
        match t {
            Tone::Primary => (self.bright, self.inverse),
            Tone::Success => (self.panel.blend(self.success.opacity(0.10)), self.ink),
            Tone::Muted => (self.secondary, self.neutral_inverse),
            Tone::Clear => (transparent_black(), self.ink),
            _ => (self.panel, self.ink),
        }
    }
}
pub fn face(
    id: impl Into<ElementId>,
    name: impl Into<SharedString>,
    height: f32,
    r: f32,
    t: Tone,
    cx: &App,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    let (bg, fg) = p.colors(t);
    let name = name.into();
    let ring = Theme::global(cx).tokens.colors.focus_outline;
    div()
        .id(id)
        .debug_selector({
            let name = name.clone();
            move || name.to_string()
        })
        .aria_label(name)
        .role(Role::Button)
        .tab_index(0)
        .h(px(height))
        .flex_none()
        .flex()
        .items_center()
        .justify_center()
        .gap(px(8.))
        .rounded(px(r))
        .bg(bg)
        .text_color(fg)
        .text_size(px(14.))
        .line_height(px(19.6))
        .font_weight(FontWeight::MEDIUM)
        .whitespace_nowrap()
        .cursor_pointer()
        .when(t == Tone::Danger, |e| {
            e.border_1().border_color(p.danger.opacity(0.42))
        })
        .when(t == Tone::Success, |e| {
            e.border_1().border_color(p.success.opacity(0.40))
        })
        .focus_visible(move |s| s.border_1().border_color(ring))
}
/// Analytic critically damped spring. Retargeting preserves instantaneous velocity.
#[derive(Clone, Copy, Debug)]
pub struct Slide {
    from: f32,
    to: f32,
    velocity: f32,
    start: Option<Instant>,
    omega: f32,
}
impl Slide {
    pub fn new(v: f32) -> Self {
        Self {
            from: v,
            to: v,
            velocity: 0.,
            start: None,
            omega: 12.47,
        }
    }
    pub fn snappy(v: f32) -> Self {
        Self {
            omega: 20.14,
            ..Self::new(v)
        }
    }
    /// Re-express the same trajectory in a shifted coordinate system, preserving velocity.
    pub fn translate(&mut self, delta: f32) {
        self.from += delta;
        self.to += delta;
    }
    pub fn reset(&mut self, v: f32) {
        self.from = v;
        self.to = v;
        self.velocity = 0.;
        self.start = None;
    }
    pub fn set(&mut self, v: f32, cx: &App) {
        self.retarget(v, self.omega, cx);
    }
    pub fn duration(&mut self, v: f32, visual_seconds: f32, cx: &App) {
        self.retarget(v, 5.236 / visual_seconds, cx)
    }
    /// Settle a directly manipulated value with the measured release speed (units per second).
    pub(crate) fn release(&mut self, target: f32, velocity: f32, seconds: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(target);
            return;
        }
        let now = cx.background_executor().now();
        self.from = self.sample(now).0;
        self.to = target;
        self.velocity = velocity;
        self.omega = 5.236 / seconds;
        self.start = Some(now);
    }
    /// Stagger a first reveal without advancing the value before its slot starts.
    pub(crate) fn delayed(&mut self, target: f32, seconds: f32, delay: f32, cx: &App) {
        if self.to == target {
            return;
        }
        self.duration(target, seconds, cx);
        if let Some(start) = self.start.as_mut() {
            *start += std::time::Duration::from_secs_f32(delay.max(0.));
        }
    }
    fn retarget(&mut self, v: f32, omega: f32, cx: &App) {
        if disabled_motion(cx) {
            self.reset(v);
            return;
        }
        if self.to == v {
            return;
        }
        let now = cx.background_executor().now();
        let (pos, vel, _) = self.sample(now);
        self.from = pos;
        self.velocity = vel;
        self.omega = omega;
        self.to = v;
        self.start = Some(now);
    }
    fn sample(&self, now: Instant) -> (f32, f32, bool) {
        let Some(start) = self.start else {
            return (self.to, 0., false);
        };
        let t = now.saturating_duration_since(start).as_secs_f32();
        let d = self.from - self.to;
        let k = self.velocity + self.omega * d;
        let e = (-self.omega * t).exp();
        let offset = (d + k * t) * e;
        let vel = (self.velocity - self.omega * k * t) * e;
        if offset.abs() < 0.0008 && vel.abs() < 0.012 || t > 1.6 {
            (self.to, 0., false)
        } else {
            (self.to + offset, vel, true)
        }
    }
    /// Sample from an input handler without scheduling a frame outside paint.
    pub fn value(&self, cx: &App) -> f32 {
        if disabled_motion(cx) {
            self.to
        } else {
            self.sample(cx.background_executor().now()).0
        }
    }
    pub fn get(&self, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return self.to;
        }
        let (v, _, m) = self.sample(cx.background_executor().now());
        if m {
            w.request_animation_frame()
        }
        v
    }
}
pub fn disabled_motion(cx: &App) -> bool {
    cx.try_global::<Theme>().is_some_and(|t| t.reduced_motion)
}
/// A finite paint clock; never schedules frames once its last phase has finished.
#[derive(Clone, Copy, Default, Debug)]
pub struct PhaseClock(Option<Instant>);
impl PhaseClock {
    pub fn restart(&mut self, cx: &App) {
        self.0 = Some(cx.background_executor().now())
    }
    pub fn age(self, cx: &App) -> f32 {
        self.0.map_or(f32::INFINITY, |s| {
            cx.background_executor()
                .now()
                .saturating_duration_since(s)
                .as_secs_f32()
        })
    }
    pub fn time(self, end: f32, w: &Window, cx: &App) -> f32 {
        if disabled_motion(cx) {
            return end;
        }
        let t = self.age(cx);
        if t < end {
            w.request_animation_frame()
        }
        t.min(end)
    }
}
pub fn ease(t: f32) -> f32 {
    cubic_out(t, 0.16, 0.30)
}
/// Cubic-bezier(.22, 1, .36, 1) used by page-scale wipes.
pub fn standard_ease(x: f32) -> f32 {
    cubic_out(x, 0.22, 0.36)
}
fn cubic_out(x: f32, x1: f32, x2: f32) -> f32 {
    if x <= 0. || x >= 1. {
        return x.clamp(0., 1.);
    }
    let (mut lo, mut hi) = (0., 1.);
    for _ in 0..14 {
        let t = (lo + hi) * 0.5;
        let v = 1. - t;
        let at = 3. * x1 * v * v * t + 3. * x2 * v * t * t + t * t * t;
        if at < x { lo = t } else { hi = t }
    }
    1. - (1. - (lo + hi) * 0.5_f32).powi(3)
}
pub fn measure(text: &SharedString, size: f32, w: &Window) -> f32 {
    let mut style = w.text_style();
    style.font_weight = FontWeight::MEDIUM;
    let advance: f32 = w
        .text_system()
        .shape_line(text.clone(), px(size), &[style.to_run(text.len())], None)
        .width
        .into();
    (advance - 0.01 * size * text.chars().count() as f32).max(0.)
}
/// Pointer feedback lives in the element's stable hit box, independent of its paint.
pub fn press<T: 'static>(
    el: Stateful<Div>,
    cx: &Context<T>,
    field: fn(&mut T) -> &mut Slide,
) -> Stateful<Div> {
    el.on_mouse_down(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(1., cx);
            cx.notify()
        }),
    )
    .on_mouse_up(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_mouse_up_out(
        MouseButton::Left,
        cx.listener(move |v, _, _, cx| {
            field(v).set(0., cx);
            cx.notify()
        }),
    )
    .on_key_down(cx.listener(move |v, e: &KeyDownEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(1., cx);
            cx.notify()
        }
    }))
    .on_key_up(cx.listener(move |v, e: &KeyUpEvent, _, cx| {
        if matches!(e.keystroke.key.as_str(), "enter" | "space") {
            field(v).set(0., cx);
            cx.notify()
        }
    }))
}

/// Stable glyph identities are matched in reading order, including common suffixes.
fn shared_glyphs(
    left: &[(SharedString, f32)],
    right: &[(SharedString, f32)],
) -> Vec<Option<usize>> {
    let stride = right.len() + 1;
    let mut lcs = vec![0u16; (left.len() + 1) * stride];
    for i in (0..left.len()).rev() {
        for j in (0..right.len()).rev() {
            lcs[i * stride + j] = if left[i].0 == right[j].0 {
                1 + lcs[(i + 1) * stride + j + 1]
            } else {
                lcs[(i + 1) * stride + j].max(lcs[i * stride + j + 1])
            };
        }
    }
    let mut out = vec![None; left.len()];
    let (mut i, mut j) = (0, 0);
    while i < left.len() && j < right.len() {
        if left[i].0 == right[j].0 {
            out[i] = Some(j);
            i += 1;
            j += 1
        } else if lcs[(i + 1) * stride + j] >= lcs[i * stride + j + 1] {
            i += 1
        } else {
            j += 1
        }
    }
    out
}
/// Paint two label phases in one measured slot; the outgoing face never affects layout.
pub fn lettering(
    old: SharedString,
    new: SharedString,
    time: f32,
    letters: bool,
    size: f32,
    ink: Hsla,
    width: f32,
) -> impl IntoElement {
    canvas(
        |_, _, _| (),
        move |b, _, w, cx| {
            let plain = old == new || time >= 0.48;
            let mut style = w.text_style();
            style.font_weight = FontWeight::MEDIUM;
            let width_of = |s: &SharedString| {
                f32::from(
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None)
                        .width,
                )
            };
            let old_x = (width - width_of(&old)) * 0.5;
            let new_x = (width - width_of(&new)) * 0.5;
            if plain {
                let mut run = style.to_run(new.len());
                run.color = ink;
                let line = w
                    .text_system()
                    .shape_line(new.clone(), px(size), &[run], None);
                let _ = line.paint(
                    b.origin + point(px(new_x), px(0.)),
                    b.size.height,
                    TextAlign::Left,
                    None,
                    w,
                    cx,
                );
                return;
            }
            let pieces = |s: &SharedString| -> Vec<(SharedString, f32)> {
                let line =
                    w.text_system()
                        .shape_line(s.clone(), px(size), &[style.to_run(s.len())], None);
                s.char_indices()
                    .map(|(i, c)| (c.to_string().into(), line.x_for_index(i).into()))
                    .collect()
            };
            let mut runs = Vec::new();
            if letters && old.len() < 256 && new.len() < 256 {
                let left = pieces(&old);
                let right = pieces(&new);
                let pairs = shared_glyphs(&left, &right);
                let mut stable = vec![false; right.len()];
                let out = 1. - standard_ease(time / 0.16);
                let layout = 1. - (1. + 12.47 * time) * (-12.47 * time).exp();
                for ((glyph, dx), matched) in left.into_iter().zip(pairs) {
                    if let Some(j) = matched {
                        let x = old_x + dx;
                        stable[j] = true;
                        runs.push((glyph, x + (new_x + right[j].1 - x) * layout, 0., 1., 0.));
                    } else {
                        runs.push((glyph, old_x + dx, -3. * (1. - out), out, 2. * (1. - out)));
                    }
                }
                let mut order = 0;
                for ((glyph, dx), matched) in right.into_iter().zip(stable) {
                    if !matched {
                        let k = ease((time - (order as f32 * 0.016).min(0.1)) / 0.24);
                        runs.push((glyph, new_x + dx, 4. * (1. - k), k, 2. * (1. - k)));
                        order += 1;
                    }
                }
            } else {
                let incoming = ease(time / 0.16);
                runs.push((old.clone(), old_x, 0., 1. - standard_ease(time / 0.10), 0.));
                runs.push((new.clone(), new_x, 2. * (1. - incoming), incoming, 0.));
            }
            for (s, x, y, alpha, blur) in runs {
                if alpha < 0.001 || s.is_empty() {
                    continue;
                }
                let taps = if blur > 0.22 { 5 } else { 1 };
                let mut run = style.to_run(s.len());
                run.color = ink.opacity(alpha / if taps == 5 { 4.3 } else { 1. });
                let line = w.text_system().shape_line(s, px(size), &[run], None);
                for (dx, dy) in [(0., 0.), (-0.7, 0.), (0.7, 0.), (0., -0.7), (0., 0.7)]
                    .into_iter()
                    .take(taps)
                {
                    let _ = line.paint(
                        b.origin + point(px(x + dx * blur), px(y + dy * blur)),
                        b.size.height,
                        TextAlign::Left,
                        None,
                        w,
                        cx,
                    );
                }
            }
        },
    )
    .w(px(width.max(0.)))
    .h(px(size * 1.4))
    .flex_none()
}

#[cfg(test)]
mod spring_tests {
    use super::{Instant, Slide};
    use std::time::Duration;
    #[test]
    fn reversing_keeps_position_and_velocity() {
        let s = Instant::now();
        let mid = s + Duration::from_millis(75);
        let a = Slide {
            start: Some(s),
            to: 1.,
            ..Slide::new(0.)
        };
        let (x, v, _) = a.sample(mid);
        let reversed = Slide {
            start: Some(mid),
            from: x,
            velocity: v,
            to: 0.,
            ..a
        };
        assert_eq!(reversed.sample(mid), (x, v, true));
        assert!(reversed.sample(mid + Duration::from_millis(240)).0 < x);
        assert_eq!(
            reversed.sample(mid + Duration::from_secs(2)),
            (0., 0., false)
        );
    }
    #[test]
    fn unchanged_suffix_keeps_its_identity_across_label_swaps() {
        let glyphs = |s: &str| {
            s.chars()
                .map(|g| (gpui::SharedString::from(g.to_string()), 0.))
                .collect::<Vec<_>>()
        };
        let old = glyphs("Add to library");
        let new = glyphs("In library");
        let pairs = super::shared_glyphs(&old, &new);
        assert_eq!(
            &pairs[old.len() - 7..],
            &[
                Some(3),
                Some(4),
                Some(5),
                Some(6),
                Some(7),
                Some(8),
                Some(9)
            ]
        );
        assert_eq!(
            super::shared_glyphs(&glyphs("添加成员"), &glyphs("移除成员")),
            vec![None, None, Some(2), Some(3)]
        );
    }
}

#[cfg(test)]
mod accent_tests {
    use super::{AccentPalette, Paint, Theme, ThemeMode};
    use gpui::{Hsla, rgb};
    #[test]
    fn custom_accent_preserves_fill_and_picks_readable_ink_in_both_modes() {
        // Color pairs include near-threshold grays and hues with high/low relative
        // luminance despite identical HSL lightness (yellow and blue).
        for (hex, expected) in [
            (0xffffff, Hsla::black()),
            (0x000000, Hsla::white()),
            (0xffff00, Hsla::black()),
            (0x0000ff, Hsla::white()),
            (0x757575, Hsla::white()),
            (0x767676, Hsla::black()),
            (0xdfa4ef, Hsla::black()),
            (0x221144, Hsla::white()),
        ] {
            let fill: Hsla = rgb(hex).into();
            let accent = AccentPalette {
                light: fill,
                dark: fill,
            };
            let mut theme = Theme::default();
            theme.set_accent(accent);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let colors = &theme.tokens.colors;
                let p = Paint::for_theme(&theme);
                assert_eq!(colors.accent, fill);
                assert_eq!(p.bright, fill);
                assert_eq!(colors.accent_foreground, expected, "#{hex:06x}");
                assert_eq!(p.inverse, expected);
                assert!(AccentPalette::contrast(p.inverse, p.bright) >= 4.5);
                assert!(AccentPalette::contrast(p.inverse, p.primary_hover(0.12)) >= 4.5);
                assert!(AccentPalette::contrast(colors.focus_outline, colors.surface_muted) >= 3.5);
                assert!(AccentPalette::contrast(colors.focus_outline, p.stage) >= 3.);
                // A tint applies to the primary fill, never to text on neutral/status surfaces.
                assert_eq!(p.neutral_inverse, Paint::for_mode(mode).inverse);
            }
        }
    }

    #[test]
    fn theme_presets_keep_their_authored_inks_and_focus_colors() {
        for (light, dark) in [
            (0x245bc4, 0x8bb4ff),
            (0x7142b6, 0xbc9cff),
            (0x08776d, 0x68d4c4),
            (0xb93c67, 0xff94b3),
            (0x955a08, 0xf4be69),
        ] {
            let mut theme = Theme::default();
            let pair = AccentPalette {
                light: rgb(light).into(),
                dark: rgb(dark).into(),
            };
            theme.set_accent(pair);
            for mode in [ThemeMode::Light, ThemeMode::Dark] {
                theme.set_mode(mode);
                let p = Paint::for_theme(&theme);
                let neutral = Paint::for_mode(mode);
                assert_eq!(p.bright, pair.for_mode(mode));
                assert_eq!(p.inverse, neutral.inverse);
                assert_eq!(theme.tokens.colors.focus_outline, pair.for_mode(mode));
            }
            theme.set_accent(AccentPalette::default());
            let p = Paint::for_theme(&theme);
            let neutral = Paint::for_mode(theme.mode);
            assert_eq!(p.bright, neutral.bright);
            assert_eq!(p.inverse, neutral.inverse);
        }
    }
}

//! Shared typography, keyboard actions and editing surfaces for workspace controls.
use crate::primitives::{
    control::{UiLanguage, activate},
    editor::{Editor, InputMode},
    family::{Paint, Tone, face},
    glyph::{Glyph, icon},
};
use gpui::{prelude::*, *};

pub fn tr(cx: &App, en: &'static str, zh: &'static str) -> &'static str {
    UiLanguage::current(cx).text(en, zh)
}
pub fn column() -> Div {
    div().flex().flex_col().min_w_0().gap(px(8.))
}
pub fn row() -> Div {
    div().flex().items_center().min_w_0().gap(px(8.))
}
pub fn panel(id: &SharedString, width: f32, cx: &App) -> Stateful<Div> {
    let p = Paint::get(cx);
    column()
        .id(id.clone())
        .w_full()
        .max_w(px(width))
        .p(px(16.))
        .gap(px(12.))
        .rounded(crate::foundation::Theme::global(cx).tokens.radius.md)
        .border_1()
        .border_color(p.line)
        .bg(p.panel)
        .text_color(p.ink)
        .text_size(px(14.))
        .line_height(px(20.))
}
pub fn title(s: impl Into<SharedString>) -> Div {
    div()
        .min_w_0()
        .font_weight(FontWeight::SEMIBOLD)
        .child(s.into())
}
pub fn note(s: impl Into<SharedString>, cx: &App) -> Div {
    div()
        .min_w_0()
        .text_size(px(12.))
        .line_height(px(17.))
        .text_color(Paint::get(cx).secondary)
        .child(s.into())
}
pub fn divider(cx: &App) -> Div {
    div().w_full().h(px(1.)).bg(Paint::get(cx).line)
}
pub fn badge(s: impl Into<SharedString>, cx: &App) -> Div {
    div()
        .flex_none()
        .text_size(px(11.))
        .px(px(6.))
        .rounded(crate::foundation::surface_radius(cx))
        .bg(Paint::get(cx).stage)
        .child(s.into())
}
pub fn btn<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    selected: bool,
    cx: &Context<T>,
    action: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let s = label.into();
    let p = Paint::get(cx);
    let el = face(
        id,
        s.clone(),
        32.,
        crate::foundation::surface_radius(cx).into(),
        if selected { Tone::Primary } else { Tone::Clear },
        cx,
    )
    .px(px(9.))
    .text_size(px(12.))
    .when(!selected, |e| e.hover(move |s| s.bg(p.hover)))
    .child(s);
    activate(el, cx, action)
}
pub fn icon_btn<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    g: Glyph,
    cx: &Context<T>,
    action: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    activate(
        face(
            id,
            label,
            30.,
            crate::foundation::surface_radius(cx).into(),
            Tone::Clear,
            cx,
        )
        .w(px(30.))
        .hover(move |s| s.bg(p.hover))
        .child(icon(g, 16., p.secondary)),
        cx,
        action,
    )
}
pub fn item<T: 'static>(
    id: impl Into<ElementId>,
    label: impl Into<SharedString>,
    cx: &Context<T>,
    action: impl Fn(&mut T, &mut Window, &mut Context<T>) + Clone + 'static,
) -> Stateful<Div> {
    let p = Paint::get(cx);
    let label = label.into();
    activate(
        row()
            .id(id)
            .debug_selector({
                let label = label.clone();
                move || label.to_string()
            })
            .aria_label(label)
            .role(Role::Button)
            .tab_index(0)
            .px(px(8.))
            .py(px(6.))
            .rounded(crate::foundation::surface_radius(cx))
            .cursor_pointer()
            .hover(move |s| s.bg(p.hover))
            .focus_visible(move |s| s.bg(p.hover).border_1().border_color(p.faint)),
        cx,
        action,
    )
}
pub fn initials(s: &str) -> String {
    s.split_whitespace()
        .filter_map(|n| n.chars().next())
        .take(2)
        .collect()
}
pub fn avatar(name: &str, i: usize, cx: &App) -> Div {
    let hue = [0x8a65ac, 0x327982, 0xab6b49, 0x5f71a1, 0x997536][i % 5];
    row()
        .size(px(28.))
        .justify_center()
        .rounded_full()
        .bg(rgb(hue).opacity(0.18))
        .text_color(Paint::get(cx).ink)
        .text_size(px(10.))
        .child(initials(name))
}
pub fn editor<T: 'static>(
    label: SharedString,
    mode: InputMode,
    w: &mut Window,
    cx: &mut Context<T>,
) -> Entity<Editor> {
    cx.new(|cx| {
        let mut e = Editor::new(label.clone(), mode, w, cx);
        e.set_placeholder(label);
        e
    })
}
pub fn input(e: &Entity<Editor>, cx: &App) -> Div {
    let p = Paint::get(cx);
    div()
        .w_full()
        .min_w_0()
        .h(px(36.))
        .flex()
        .items_center()
        .px(px(8.))
        .rounded(crate::foundation::surface_radius(cx))
        .border_1()
        .border_color(p.line)
        .bg(p.panel)
        .child(e.clone())
}
pub fn replace(e: &Entity<Editor>, s: impl Into<String>, w: &Window, cx: &mut App) {
    e.update(cx, |e, cx| e.set_value(s, w, cx))
}
pub fn bar(fraction: f32, color: Hsla, cx: &App) -> Div {
    div()
        .w_full()
        .h(px(5.))
        .rounded_full()
        .overflow_hidden()
        .bg(Paint::get(cx).stage)
        .child(
            div()
                .h_full()
                .w(relative(fraction.clamp(0., 1.)))
                .rounded_full()
                .bg(color),
        )
}

/// Reveal a newly mounted element once. Stable IDs keep unrelated rerenders from replaying it.
pub fn arrive<E: IntoElement + Styled + 'static>(
    element: E,
    id: impl Into<ElementId>,
    delay_ms: u64,
    rise: f32,
    cx: &App,
) -> AnyElement {
    if crate::primitives::family::disabled_motion(cx) {
        return element.into_any_element();
    }
    let total = (160 + delay_ms) as f32;
    element
        .with_animation(
            id,
            Animation::new(std::time::Duration::from_millis(160 + delay_ms)),
            move |el, t| {
                let t = ((t * total - delay_ms as f32) / 160.).clamp(0., 1.);
                el.relative().top(px(rise * (1. - t))).opacity(t)
            },
        )
        .into_any_element()
}

/// Retains the natural height of a disclosure while it closes. The spring can be
/// retargeted before settling and reads reduced motion from the same scene.
pub struct Fold {
    amount: f32,
    height: std::rc::Rc<std::cell::Cell<Pixels>>,
    open: bool,
}
impl Fold {
    pub fn get(
        key: impl Into<ElementId>,
        open: bool,
        estimate: f32,
        seconds: f32,
        w: &mut Window,
        cx: &mut App,
    ) -> Self {
        use crate::primitives::family::Slide;
        struct State {
            open: bool,
            phase: Slide,
            height: std::rc::Rc<std::cell::Cell<Pixels>>,
        }
        let state = w.use_keyed_state(key, cx, |_, _| State {
            open,
            phase: Slide::new(f32::from(open)),
            height: std::rc::Rc::new(std::cell::Cell::new(px(estimate))),
        });
        state.update(cx, |s, cx| {
            if s.open != open {
                s.open = open;
                s.phase.duration(f32::from(open), seconds, cx)
            }
            Self {
                amount: s.phase.get(w, cx).clamp(0., 1.),
                height: s.height.clone(),
                open,
            }
        })
    }
    pub fn mounted(&self) -> bool {
        self.open || self.amount > 0.001
    }
    pub fn wrap(self, parent_gap: f32, content: impl IntoElement) -> Div {
        let h = self.height.get();
        // The scrolling parent owns clipping once a disclosure is open. Shrinking
        // individual rows would trim the last action in every wrapped toolbar.
        let shell = div()
            .mt(px(-parent_gap * (1. - self.amount)))
            .w_full()
            .flex_none()
            .when(self.amount < 0.999, |v| {
                v.h(h * self.amount).overflow_hidden()
            })
            .opacity(self.amount);
        shell.child(
            div()
                .w_full()
                .flex_none()
                .on_children_prepainted(move |bounds, _, _| {
                    if let Some(b) = bounds.first()
                        && b.size.height > px(0.)
                    {
                        self.height.set(b.size.height);
                    }
                })
                .child(content),
        )
    }
}

/// Paint both labels during a compact status change, preserving the interrupted mix.
pub fn swap_label(
    key: impl Into<ElementId>,
    text: impl Into<SharedString>,
    w: &mut Window,
    cx: &mut App,
) -> Div {
    swap_label_after(key, text, 0., w, cx)
}
/// Delay the crossfade for later cards without shifting neighboring cards.
pub fn swap_label_after(
    key: impl Into<ElementId>,
    text: impl Into<SharedString>,
    delay: f32,
    w: &mut Window,
    cx: &mut App,
) -> Div {
    use crate::primitives::family::PhaseClock;
    let next = text.into();
    struct Labels {
        previous: Vec<(SharedString, f32)>,
        current: SharedString,
        clock: PhaseClock,
    }
    let state = w.use_keyed_state(key, cx, |_, _| Labels {
        previous: vec![],
        current: next.clone(),
        clock: Default::default(),
    });
    state.update(cx, |s, cx| {
        let age = (s.clock.time(0.16 + delay, w, cx) - delay).max(0.);
        if s.current != next {
            let fade = (1. - age / 0.10).clamp(0., 1.);
            for (_, weight) in &mut s.previous {
                *weight *= fade
            }
            s.previous.retain(|(_, alpha)| *alpha > 0.01);
            let weight = (age / 0.16).clamp(0., 1.);
            if weight > 0.01 {
                s.previous.push((s.current.clone(), weight))
            }
            s.current = next;
            s.clock.restart(cx);
        }
        let age = (s.clock.time(0.16 + delay, w, cx) - delay).max(0.);
        let enter = (age / 0.16).clamp(0., 1.);
        let exit = (1. - age / 0.10).clamp(0., 1.);
        if exit == 0. {
            s.previous.clear()
        }
        div()
            .relative()
            .child(
                div()
                    .id("incoming-label")
                    .debug_selector({
                        let n = s.current.clone();
                        move || format!("Incoming {n}")
                    })
                    .relative()
                    .top(px(2. * (1. - enter)))
                    .opacity(enter)
                    .child(s.current.clone()),
            )
            .children(s.previous.iter().map(|(old, a)| {
                div()
                    .absolute()
                    .top(px(-2. * (1. - exit)))
                    .left_0()
                    .opacity(a * exit)
                    .child(old.clone())
            }))
    })
}

/// Retarget a finite numeric transition once per value change.
pub fn animated_value(
    key: impl Into<ElementId>,
    value: f32,
    duration: f32,
    w: &mut Window,
    cx: &mut App,
) -> f32 {
    use crate::primitives::family::Slide;
    let state = w.use_keyed_state(key, cx, |_, _| (value, Slide::new(value)));
    state.update(cx, |s, cx| {
        if s.0 != value {
            s.0 = value;
            s.1.duration(value, duration, cx)
        }
        s.1.get(w, cx)
    })
}

/// Opacity belongs to each appended byte range, so the preceding words keep
/// fading independently when another partial result arrives.
pub fn stream_highlights(
    key: impl Into<ElementId>,
    value: &str,
    w: &mut Window,
    cx: &mut App,
) -> Vec<(std::ops::Range<usize>, HighlightStyle)> {
    use crate::primitives::family::PhaseClock;
    type Chunk = (std::ops::Range<usize>, PhaseClock);
    let state = w.use_keyed_state(key, cx, |_, _| (String::new(), Vec::<Chunk>::new()));
    state.update(cx, |s, cx| {
        if value != s.0 {
            let offset = if value.starts_with(&s.0) {
                s.0.len()
            } else {
                s.1.clear();
                0
            };
            if offset < value.len() {
                let mut clock = PhaseClock::default();
                clock.restart(cx);
                s.1.push((offset..value.len(), clock))
            }
            s.0.clear();
            s.0.push_str(value);
        }
        let ink = Paint::get(cx).ink;
        let mut spans = vec![];
        s.1.retain(|(range, clock)| {
            let t = clock.time(0.14, w, cx) / 0.14;
            if t < 1. {
                spans.push((
                    range.clone(),
                    HighlightStyle {
                        color: Some(ink.opacity(t)),
                        ..Default::default()
                    },
                ));
                true
            } else {
                false
            }
        });
        spans
    })
}
